<script>
document.querySelectorAll('.mobile-date-btn').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.mobile-date-btn').forEach(x=>x.classList.toggle('active',x===btn));document.querySelectorAll('.mobile-lesson-panel').forEach(x=>x.classList.toggle('active',x.dataset.panel===btn.dataset.lesson));btn.scrollIntoView({behavior:'smooth',inline:'center',block:'nearest'})}));
document.addEventListener('change',async e=>{if(!e.target.matches('.att,.grd'))return;const cell=e.target.closest('.gb-cell'),msg=cell.parentElement.querySelector('.gb-save');const body={student_id:cell.dataset.student};if(e.target.classList.contains('att'))body.attendance=e.target.value;else{if(!e.target.value)return;body.grade=e.target.value}msg.textContent='Сохранение…';try{const res=await fetch(cell.dataset.url,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify(body)});if(!res.ok)throw new Error();msg.textContent='Сохранено';if(body.grade){const box=cell.parentElement.querySelector('.gb-grades');box.insertAdjacentHTML('beforeend',' <span class="badge text-bg-success">'+body.grade+'</span>');e.target.value=''}}catch(x){msg.textContent='Ошибка сохранения';e.target.classList.add('is-invalid')}setTimeout(()=>msg.textContent='',1800)});
</script>
